  "Ich mach gerade eine Ausbildung als Krankenpfleger.": "Je suis en formation d'infirmier en ce moment.",
  "Nach der Ausbildung will sie noch studieren.": "Après sa formation, elle veut encore faire des études.",
  "Ich studiere an der Universität Köln.": "J'étudie à l'université de Cologne.",
  "Sie ist an einer Hochschule für Musik.": "Elle est dans un conservatoire supérieur de musique.",
  "Wie lange dauert dein Studium noch?": "Tes études durent encore combien de temps ?",
  "Ich hab mein Studium letztes Jahr abgeschlossen.": "J'ai terminé mes études l'année dernière.",
